import { validate, ValidationResult } from './validator';

describe('validate', () => {
  it('should return valid when all required fields are present and non-falsy', () => {
    const schema = { required: ['name', 'age'] };
    const data = { name: 'Alice', age: 30 };
    const result = validate(data, schema);
    expect(result.valid).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

  it('should return invalid when a required field is missing', () => {
    const schema = { required: ['name', 'age'] };
    const data = { name: 'Alice' };
    const result = validate(data, schema);
    expect(result.valid).toBe(false);
    expect(result.errors).toContain('Missing required field: age');
  });

  it('should return invalid when input is not an object', () => {
    const schema = { required: ['name'] };
    const result = validate(null, schema);
    expect(result.valid).toBe(false);
    expect(result.errors).toContain('Input must be an object');
  });

  // Test case for the bug fix: allowing falsy but valid values (0, "", false)
  it('should return valid when required fields are present but have falsy values (0, "", false)', () => {
    const schema = { required: ['count', 'name', 'isActive'] };
    const data = { count: 0, name: "", isActive: false };
    const result = validate(data, schema);
    expect(result.valid).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

  it('should return invalid when required field is explicitly undefined', () => {
    const schema = { required: ['name', 'age'] };
    const data = { name: 'Bob', age: undefined };
    const result = validate(data, schema);
    expect(result.valid).toBe(false);
    expect(result.errors).toContain('Missing required field: age');
  });
});

